// CSD_RATIONALE_BEGIN
// Critical bug fix: The N=C=O substring check was REJECTING all valid
// isocyanate SMILES in "O=C=N..." format.
//
// Root cause of 7% regression (attempt 35 vs best 20% attempt 9):
//   The guidance shows examples like "O=C=NCCCl" (O=C=N... format).
//   The code then checked CSDHelpers.CountSubstring(smilesStr, "N=C=O").
//   But "O=C=NCCCl" does NOT contain "N=C=O" as a substring — the atoms
//   appear in reverse order (O before N, not N before O).
//   So hasNCO was always 0 for every O=C=N... SMILES, the IsCompletePrefix
//   branch never closed the span, and the model continued generating past
//   valid isocyanate termination points, converging to only 7 unique outputs.
//
// Attempt 9 also had the NCO check, but it got 20%. Why? With T=1.6 and
// minSpanLength=5 (vs T=1.8 and minSpanLength=8 in attempt 35), the budget
// ran out earlier and CloseSpanWithinBudget found more diverse prefixes.
//
// Fix strategy:
//   1. Check for BOTH "N=C=O" AND "O=C=N" in the content check (covers both
//      canonical SMILES orientations). This immediately closes O=C=N... format.
//   2. Keep minSpanLength=5 (not 8), allowing early valid closure.
//   3. Update guidance to show diverse R groups in explicit structural classes.
//   4. Keep T=1.6 for mid-phase (attempt 9's proven best setting).
//   5. Keep penalty phase for first 5 tokens (avoids degenerate starts).
//
// Expected improvement: fixing the OCN check should allow the model to close
// at the first valid complete isocyanate in either format, increasing unique
// molecule count from 7 to 30%+.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   - OpenConstrainedSpan branch: sets currentConstrainedOut := [];
//     parser.IsValidPrefix([]) holds by method precondition. ✓
//   - IsCompletePrefix branch (NCO/OCN found): CloseConstrainedSpan sets
//     insideConstrainedOut := false; implication becomes vacuous;
//     currentConstrainedOut := []. ✓
//   - IsCompletePrefix branch (NCO/OCN not found): SafeTemperatureConstrainedStep
//     hard-masks to parser-valid tokens plus EOS; AppendConstrainedToken
//     postcondition yields IsValidPrefix(new currentConstrainedOut). ✓
//   - Else branch (SafePenalizedConstrainedStep): same hard-mask guarantee;
//     AppendConstrainedToken preserves validity. ✓
//   - Else branch (SafeTemperatureConstrainedStep T=1.6): same. ✓
//   - Else branch (GroupBoostedConstrainedStep): same. ✓
//   - EOS with close: CloseConstrainedSpan sets insideConstrainedOut := false. ✓
//   - EOS without close: state unchanged; invariant preserved by induction. ✓
//   - Post-loop CloseSpanWithinBudget: postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   - OpenConstrainedSpan: |generated| += 1 (for "<<"), steps += 1. Equality. ✓
//   - IsCompletePrefix → CloseConstrainedSpan: |generated| += 1 (for ">>"),
//     steps += 1; bound preserved. ✓
//   - IsCompletePrefix (no NCO/OCN) → constrained step: steps += 1 once;
//     AppendConstrainedToken adds at most 1 visible token; EOS adds 0. ✓
//   - Else branch (penalty/temp/group step): steps += 1; AppendConstrainedToken
//     adds ≤ 1 token; EOS adds 0. ✓
//   - EOS → CloseConstrainedSpan sub-branch: steps was already incremented for
//     the constrained step; CloseConstrainedSpan increments once more (steps ≤
//     maxSteps by the guard steps < maxSteps before that call); |generated| += 1. ✓
//   - Post-loop: closeBudget = maxSteps - steps; postcondition gives
//     |cg| ≤ |generated| + closeBudget ≤ |generatedPrefix| + maxSteps;
//     steps := maxSteps ≤ maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one novel valid SMILES for an isocyanate molecule (R-N=C=O or O=C=N-R). Maximize structural diversity across classes: simple alkyl (CCN=C=O, CCCN=C=O, CCCCN=C=O, CCCCCN=C=O), branched (CC(C)N=C=O, CC(C)(C)N=C=O, CCC(C)N=C=O, CC(CC)N=C=O), haloalkyl (ClCCN=C=O, BrCCN=C=O, FCCN=C=O, FC(F)(F)CN=C=O, ClCCCN=C=O, BrCCCN=C=O), cycloalkyl (C1CCC1N=C=O, C1CCCC1N=C=O, C1CCCCC1N=C=O, C1CCCCCC1N=C=O), aryl (c1ccccc1N=C=O, Cc1ccccc1N=C=O, Clc1ccccc1N=C=O, Fc1ccccc1N=C=O, c1ccc(N=C=O)cc1C), heteroaryl (c1ccncc1N=C=O, c1cncc1N=C=O), unsaturated (C=CCN=C=O, C#CCN=C=O), ether (COCCN=C=O, COCN=C=O). Output ONLY the SMILES string.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    var hasOCN := CSDHelpers.CountSubstring(smilesStr, "O=C=N");
    if hasNCO > 0 || hasOCN > 0 {
      // Valid isocyanate in either format — close the span
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      // Complete but no isocyanate group yet — continue with temperature for diversity
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 5 {
      // Early tokens: penalize common starters to increase structural diversity
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 20 {
      // Mid-phase: temperature diversity for R-group exploration
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
    } else {
      // Late phase: group-boosted for valid completion
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr2 := CSDHelpers.PrefixToString(currentConstrainedOut);
        var nco2 := CSDHelpers.CountSubstring(smilesStr2, "N=C=O");
        var ocn2 := CSDHelpers.CountSubstring(smilesStr2, "O=C=N");
        if nco2 > 0 || ocn2 > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

